using Microsoft.EntityFrameworkCore;

public sealed record CustomerSummary(int Id, string Name);

public static Task<List<CustomerSummary>> NextPageAsync(
    AppDbContext database, int afterId, CancellationToken cancellationToken)
{
    return database.Customers.AsNoTracking()
        .Where(customer => customer.Id > afterId)
        .OrderBy(customer => customer.Id)
        .Select(customer => new CustomerSummary(customer.Id, customer.Name))
        .Take(20)
        .ToListAsync(cancellationToken);
}

