using Microsoft.Extensions.Caching.Hybrid;

public sealed class ProductCache(HybridCache cache, ProductStore store)
{
    public ValueTask<Product?> GetAsync(int productId, CancellationToken cancellationToken)
        => cache.GetOrCreateAsync(
            $"public-product:{productId}",
            token => store.LoadAsync(productId, token),
            new HybridCacheEntryOptions { Expiration = TimeSpan.FromMinutes(2) },
            cancellationToken: cancellationToken);
}

public sealed record Product(int Id, string Name);
public abstract class ProductStore
{
    public abstract ValueTask<Product?> LoadAsync(int productId, CancellationToken cancellationToken);
}

